mutation externalRefreshWithUser($pluginId: String = "mirumee.authentication.openidconnect", $input: JSONString!) {
  externalRefresh(pluginId: $pluginId, input: $input) {
    token
    refreshToken
    user {
      ...UserDetailsFragment
    }
    errors {
      ...AccountErrorFragment
    }
  }
}

fragment UserDetailsFragment on User {
  ...UserBaseFragment
  metadata {
    key
    value
  }
  defaultShippingAddress {
    ...AddressFragment
  }
  defaultBillingAddress {
    ...AddressFragment
  }
  addresses {
    ...AddressFragment
  }
}

fragment UserBaseFragment on User {
  id
  email
  firstName
  lastName
  isStaff
  userPermissions {
    code
    name
  }
}

fragment AddressFragment on Address {
  id
  firstName
  lastName
  companyName
  streetAddress1
  streetAddress2
  city
  cityArea
  postalCode
  country {
    code
    country
  }
  countryArea
  phone
  isDefaultBillingAddress
  isDefaultShippingAddress
}

fragment AccountErrorFragment on AccountError {
  code
  field
  message
}
